//! THE RATCHET: no NEW `.rs` file appears under `crates/` or `src-tauri/src/`.
//!
//! MEASURED 2026-09-05 over one session (`e2f13ace5..fe7bd8588`): ~10,000 lines were moved OUT of crate
//! roots and into the graph, while 44 new `.rs` files / 13,921 lines were added by concurrent work. A
//! migration is a one-time sweep and authoring is continuous, so the sweep loses. This is the third
//! guard in the pair's shape, and it is the one that closes the two holes the other two cannot see.
//!
//! # What the other two guards miss
//!
//! `no_crate_carries_the_build_key_with_its_modules_still_on_disk` judges declared MODULES, so a new
//! `crates/<x>/tests/` target passes it. `no_adopter_has_regrown_a_private_crate_root` judges crates
//! that already carry the build key, so a brand-new crate that never adopts is invisible to it.
//! `a_crate_root_holds_no_inline_test_module` judges INLINE test modules only. Between them: a whole
//! new crate, and a whole new integration-test target, both land green.
//!
//! So this one judges the only thing that has no exceptions of its own — a `.rs` FILE existing at all.
//!
//! # Why an allow-list rather than a count
//!
//! Copied verbatim from `crate_root_tests`, because the reasoning is the same and a second shape would
//! be a second thing to learn. The assertion is SUBSET, not equality: a session that MIGRATES a file
//! never has to edit [`ON_DISK`] to stay green, so cleaning is never a merge conflict for whoever lands
//! first — while a session that ADDS one goes red, and the edit that makes it green again is the
//! conversation this guard exists to force. A count would let one file migrate and another appear with
//! the total unchanged.
//!
//! # Why the population is asserted
//!
//! A scanner that silently stops matching finds zero files, reports zero offenders, and reads as a
//! pass. So the scan asserts it found the tree before it says anything about what is in it.

use std::path::{Path, PathBuf};

/// The repo root — two levels above `crates/bsc-graph`.
fn repo_root() -> PathBuf {
    let root = Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .and_then(Path::parent)
        .expect("crates/<name> is two deep")
        .to_path_buf();
    assert!(
        std::fs::read_to_string(root.join("Cargo.toml")).is_ok_and(|t| t.contains("[workspace]")),
        "the workspace root must be two levels above this crate — found {}",
        root.display()
    );
    root
}

/// Every `.rs` file under `crates/` and `src-tauri/src/`, repo-relative with `/` separators, sorted.
///
/// EVERY one — a crate root, a declared child, a `tests/` target, a fixture, an example, a build
/// script. Narrowing the scan is how the other guards ended up with the holes this one exists to
/// close, so the scan is total and the EXCEPTIONS are named instead.
fn rust_files(root: &Path) -> Vec<String> {
    fn walk(dir: &Path, root: &Path, out: &mut Vec<String>) {
        let Ok(entries) = std::fs::read_dir(dir) else { return };
        for e in entries.flatten() {
            let name = e.file_name().to_string_lossy().to_string();
            // A dot-directory is not source, and `target/` is build output that would swamp the scan.
            if name.starts_with('.') || name == "target" {
                continue;
            }
            let p = e.path();
            if p.is_dir() {
                walk(&p, root, out);
            } else if name.ends_with(".rs") {
                out.push(p.strip_prefix(root).unwrap_or(&p).display().to_string().replace('\\', "/"));
            }
        }
    }
    let mut out = Vec::new();
    walk(&root.join("crates"), root, &mut out);
    walk(&root.join("src-tauri").join("src"), root, &mut out);
    out.sort();
    out
}

/// Crates this guard does not judge at all, each with the reason it does not.
///
/// A GATE THAT REDDENS SOMEBODY ELSE'S IN-FLIGHT FEATURE GETS DISABLED, and then it protects nothing.
/// These are whole-crate exceptions rather than per-file ones on purpose: a lane mid-feature adds files
/// by the hour, and a per-file list for one would be a merge conflict every time its author saved.
///
/// Removing an entry is how a lane opts IN once it settles — which is a decision for that lane's
/// session, not for this one.
const EXEMPT_CRATES: &[&str] = &[
    // THE MACHINERY MIGRATION DEPENDS ON. `build.rs`, `crate_root.rs`, `test_root.rs`, `plan.rs` and
    // `emit.rs` are read from disk by cargo and by ~54 crates' `build =` key, so they can never be
    // records — a record of the materializer would have to be materialized by itself. `src/lib.rs`,
    // `src/tests.rs` and `src/test_targets.rs` are this package's own test target, which exists only
    // because a build script has none, and which must compile before any adopter can build.
    "graph-materialize",
    // OTHER LANES, MID-FEATURE as of 2026-09-05. Each belongs to another session and is being authored
    // right now; the ratchet is about NEW drift in settled crates, not about interrupting work in
    // progress. `bsc-lan` additionally is not wired to the materializer yet (see `STILL_INLINE` in
    // `crate_root_tests`), so its files have nowhere to go until `migrate-crate bsc-lan --apply` runs.
    "bsc-ear",
    "bsc-say",
    "bsc-lan",
    "bsc-lan-core",
    "bsc-lan-sense",
    "bsc-lan-stream",
    "bsc-rf",
];

/// The `.rs` files that were on disk when this guard was written, outside [`EXEMPT_CRATES`].
///
/// GENERATED FROM THE TREE, never typed. It was 66 entries at `fe7bd8588`, most of them crate roots
/// still holding real code; `the-crate-root-implementations-move-into-the-graph` moved 46 of those
/// roots into records, so this is the 20 that are left — and NOT ONE OF THEM IS A CRATE ROOT WITH A
/// PROGRAM IN IT. Every survivor is here because cargo resolves it from disk (a build script, a
/// `tests/` target, an `example/`), because it is text a test parses, or because its package has two
/// roots and one `$OUT_DIR`. Each carries that reason beside it.
///
/// SUBSET, not equality, for the VERDICT: migrating any of these needs no edit here. Pruning the dead
/// entry afterwards is not optional housekeeping though —
/// [`every_named_exception_is_a_crate_that_exists`] fails once half the list is stale, which is what
/// forced this rewrite rather than leaving 46 lies in place.
const ON_DISK: &[&str] = &[
    // A BUILD SCRIPT IS READ FROM DISK BY CARGO. `bsc-config` and `data` each own one that does other
    // jobs and calls `graph_materialize::emit()` from it — the `--alongside` route — so the file is the
    // mechanism, not a module that failed to migrate.
    "crates/bsc-config/build.rs",
    "crates/data/build.rs",
    // A `tests/` INTEGRATION TARGET. Cargo resolves each one from disk; the materializer emits a
    // lib/bin crate and its `tests/` targets from records, and these three predate that.
    "crates/bsc-disk/tests/real_trees_parity.rs",
    "crates/bsc-github/tests/transport.rs",
    "crates/bsc-publish/tests/board_adoption.rs",
    "crates/bsc-publish/tests/idempotency.rs",
    // A LIB+BIN PACKAGE CAN MIGRATE ONLY ONE ROOT, and that is arithmetic rather than a gap.
    // `$OUT_DIR/crate.rs` is per-PACKAGE, so pointing both `[lib] path` and `[[bin]] path` at
    // `crates/graph-materialize/crate_root.rs` would compile the same program twice under two names.
    // `bsc-emit`'s library is a record; its binary is the thin `main` that calls into it and stays.
    "crates/bsc-emit/src/main.rs",
    // PARSER INPUT, not code. These two are read as TEXT by this crate's own harvest tests; they sit
    // below `tests/` rather than in it, so cargo compiles neither as a target. A record of a fixture
    // would leave the test with nothing on disk to parse.
    "crates/bsc-graph/tests/fixtures/sample.rs",
    "crates/bsc-graph/tests/fixtures/signatures.rs",
    // AN EXAMPLE HAS NO RECORD TIER. `cargo run --example` resolves a target from disk and the
    // materializer emits a lib/bin crate and its `tests/` targets, nothing else. Until an example can
    // be a record these stay files, and a NEW one is a question worth being asked.
    "crates/bsc-sandbox/examples/render.rs",
    "crates/bsc-sandbox/examples/role.rs",
    "crates/bsc-storefs/examples/coord-drain.rs",
    "crates/bsc-storefs/examples/launch.rs",
    "crates/bsc-storefs/examples/project.rs",
    "crates/bsc-storefs/examples/stores.rs",
    "crates/bsc-storefs/examples/ui-drain.rs",
    // `src-tauri` IS THE ONE NAMED NON-CANDIDATE for the root migration. `main.rs` carries
    // `#![cfg_attr(not(debug_assertions), windows_subsystem = "windows")]`, the single inner attribute
    // in the tree with no `[lints]` manifest home — and the package is lib+bin besides, so `lib.rs`
    // is the other half of the arithmetic above.
    "src-tauri/src/lib.rs",
    "src-tauri/src/main.rs",
    "src-tauri/src/mobile/push.rs",
    "src-tauri/src/tests.rs",
];

/// The crate argument `migrate-crate` takes for `path` — the crate directory's LAST SEGMENT.
///
/// `crates/plandb/src/x.rs` is `plandb`; `src-tauri/src/x.rs` is `src-tauri`. That is what
/// `resolve_crate_dir` matches on, which is why `src-tauri` is nameable at all.
fn crate_arg(path: &str) -> &str {
    path.strip_prefix("crates/").map_or("src-tauri", |rest| rest.split('/').next().unwrap_or(rest))
}

/// The command that would migrate `path`, chosen by its TIER.
///
/// A gate that says "this is wrong" without saying "run this" gets worked around, so the tier that has
/// a verb hands over the verb and the tier that has none says so plainly — the honest answer being an
/// entry in [`ON_DISK`] with the reason beside it, which is a decision rather than a workaround.
fn migration_verb(path: &str) -> String {
    let krate = crate_arg(path);
    // The path BELOW the crate directory — `build.rs`, `tests/x.rs`, `src/a/b.rs`. It is the tier.
    let rest = match path.strip_prefix("crates/") {
        Some(r) => r.split_once('/').map_or("", |(_, r)| r),
        None => path.strip_prefix("src-tauri/").unwrap_or(path),
    };
    let stem = path.rsplit('/').next().unwrap_or(path).trim_end_matches(".rs");

    if rest == "build.rs" {
        return format!(
            "a build script is read from DISK by cargo and can never be a record. Reach the \
             materializer from the one you have:\n      bsc graph migrate-crate {krate} --alongside \
             --apply --root \"$PWD\"\n    …then add this path to ON_DISK with that reason beside it."
        );
    }
    // A cargo integration-test target is a FLAT file in `tests/`; anything deeper is fixture or helper.
    if let Some(t) = rest.strip_prefix("tests/") {
        if !t.contains('/') {
            return format!(
                "bsc graph edge set --id {krate}--{} --members <the records it spans> --src {path}\n    \
                 bsc graph promote --id {krate}--{} --root \"$PWD\"\n    rm {path}",
                stem.replace('_', "-"),
                stem.replace('_', "-")
            );
        }
        return "a file below `tests/` is not a cargo target — it is fixture or helper text a target \
                reads. If it must be on disk, add it to ON_DISK with that reason beside it."
            .to_string();
    }
    if rest.starts_with("examples/") {
        return "an example is a cargo target with no record tier — the materializer emits a crate and \
                its `tests/` targets, nothing else. Add it to ON_DISK with that reason beside it."
            .to_string();
    }
    format!("bsc graph migrate-crate {krate} --apply --root \"$PWD\"")
}

/// NEW WORK GOES INTO THE GRAPH, NOT ONTO DISK.
///
/// The failure names the FILE and the VERB, because "something drifted" is not actionable and the fix
/// is one pasteable command for every tier that has one.
#[test]
fn no_new_rust_file_has_appeared_outside_the_named_list() {
    let root = repo_root();
    let files = rust_files(&root);
    // A scanner that stops matching finds nothing, reports nothing, and reads as a pass.
    //
    // THE FLOOR ONLY EVER FALLS as crates reach the real floor (a `Cargo.toml` and nothing else), so
    // lower it when files legitimately leave — never raise it to quiet a red, because the number is
    // here to catch a scan that stopped walking. 108 at `fe7bd8588`; 62 after
    // `the-crate-root-implementations-move-into-the-graph`, of which 42 are in an exempt crate.
    assert!(
        files.len() >= 60,
        "found only {} .rs files under crates/ and src-tauri/src — the scan is broken, so its verdict \
         about new files is worthless",
        files.len()
    );

    let offenders: Vec<String> = files
        .iter()
        .filter(|p| !ON_DISK.contains(&p.as_str()))
        .filter(|p| !EXEMPT_CRATES.contains(&crate_arg(p)))
        .map(|p| format!("{p}\n    {}", migration_verb(p)))
        .collect();

    assert!(
        offenders.is_empty(),
        "{} new .rs file(s) appeared under crates/ or src-tauri/src. New work belongs in the graph — a \
         file the crate compiles from disk is a second live copy of a module, and the migration cannot \
         catch up with authoring one sweep at a time:\n  {}\n\n\
         If a file genuinely has to stay on disk, add it to ON_DISK in this module with the reason \
         written beside it. That edit is the conversation this guard exists to force, not a way around \
         it — and it is the only edit here that is ever needed, because the check is a SUBSET and \
         MIGRATING a file requires no edit at all.",
        offenders.len(),
        offenders.join("\n  ")
    );
}

/// The scan and the verb are pinned on SYNTHETIC paths, so migrating the last real file cannot turn
/// either into a tautology.
#[test]
fn the_verb_matches_the_tier_the_path_names() {
    assert_eq!(crate_arg("crates/plandb/src/lib.rs"), "plandb");
    assert_eq!(crate_arg("src-tauri/src/mobile/push.rs"), "src-tauri");

    // A declared child and a crate root take the SAME verb — `migrate-crate` harvests both since
    // `the-crate-body-is-a-record-not-only-its-children`.
    let root = migration_verb("crates/plandb/src/lib.rs");
    assert_eq!(root, "bsc graph migrate-crate plandb --apply --root \"$PWD\"");
    assert_eq!(migration_verb("crates/plandb/src/deep/child.rs"), root);
    assert_eq!(
        migration_verb("src-tauri/src/mobile/push.rs"),
        "bsc graph migrate-crate src-tauri --apply --root \"$PWD\""
    );

    // A FLAT `tests/` file is a cargo target, and its verb is the edge tier.
    let t = migration_verb("crates/bsc-publish/tests/board_adoption.rs");
    assert!(t.starts_with("bsc graph edge set --id bsc-publish--board-adoption "), "{t}");
    assert!(t.contains("--src crates/bsc-publish/tests/board_adoption.rs"), "{t}");
    assert!(t.contains("bsc graph promote --id bsc-publish--board-adoption"), "{t}");

    // Deeper than flat is not a target, and neither is an example or a build script — each says so
    // rather than handing over a command that would not work.
    for (path, want) in [
        ("crates/bsc-graph/tests/fixtures/sample.rs", "not a cargo target"),
        ("crates/bsc-sandbox/examples/role.rs", "no record tier"),
        ("crates/data/build.rs", "read from DISK by cargo"),
    ] {
        let v = migration_verb(path);
        assert!(v.contains(want), "{path}: expected `{want}` in:\n{v}");
        assert!(v.contains("ON_DISK"), "{path}: a tier with no verb must name the honest alternative");
    }
    // …and the build-script one still hands over the route that DOES exist.
    assert!(migration_verb("crates/data/build.rs").contains("migrate-crate data --alongside --apply"));
}

/// The scan reads the REAL tree, and every named exception is real.
///
/// A stale [`EXEMPT_CRATES`] entry is the failure mode that matters most: it is a hole with nobody
/// watching it, and unlike a stale [`ON_DISK`] entry it silences a whole directory. So a crate that has
/// left the tree must be removed from the list rather than left as a standing carve-out.
#[test]
fn every_named_exception_is_a_crate_that_exists() {
    let root = repo_root();
    for krate in EXEMPT_CRATES {
        assert!(
            root.join("crates").join(krate).join("Cargo.toml").is_file(),
            "`{krate}` is exempted but is not a crate in this tree — a carve-out for a directory that \
             is gone silences nothing and hides nothing. Delete the entry."
        );
    }
    // And every ON_DISK entry was real when written; a stale one is harmless to the verdict but is a
    // lie about the tree, so it is reported as a COUNT rather than each one failing the run.
    let files = rust_files(&root);
    let stale: Vec<&&str> = ON_DISK.iter().filter(|p| !files.contains(&p.to_string())).collect();
    assert!(
        stale.len() < ON_DISK.len() / 2,
        "{} of {} ON_DISK entries no longer exist — this list was generated from a different tree:\n  \
         {:?}",
        stale.len(),
        ON_DISK.len(),
        stale
    );
}
